import binascii

hex_data = ""

data = binascii.unhexlify(hex_data)

print(f"Total length: {len(data)} bytes")

# Assuming array of structs. Let's find patterns like 08xxxxxx (ROM pointers)
import struct

pointers = []
for i in range(len(data) - 3):
    val = struct.unpack('<I', data[i:i+4])[0]
    if 0x08000000 <= val < 0x08FFFFFF:
        pointers.append((i, hex(val)))

for p in pointers:
    print(f"Offset 0x{p[0]:02X}: Pointer {p[1]}")

# Let's group them into logical struct sizes.
# Look at the first pointer: Offset 0x3C -> 0x082a3695
# Next pointer: Offset 0x40 -> 0x082a36bc
# Next pointer: Offset 0x8C -> 0x082a3750
# Next pointer: Offset 0x90 -> 0x082a374c
# Let's assume struct size is 0x50 (80 bytes) because 0x8C - 0x3C = 0x50

struct_size = 0x50
for i in range(0, len(data), struct_size):
    chunk = data[i:i+struct_size]
    print(f"\nStruct {i // struct_size}:")
    for j in range(0, len(chunk), 4):
        if j+4 <= len(chunk):
            val = struct.unpack('<I', chunk[j:j+4])[0]
            val_hex = f"{val:08X}"
            print(f"  +0x{j:02X}: {val_hex}  ({struct.unpack('<i', chunk[j:j+4])[0]})")

